package java.util.concurrent;
public class ForkJoinPool extends AbstractExecutorService {private static final ForkJoinPool COMMON=new ForkJoinPool();private boolean shutdown;public ForkJoinPool(){}public ForkJoinPool(int n){if(n<=0)throw new IllegalArgumentException();}public static ForkJoinPool commonPool(){return COMMON;}public static int getCommonPoolParallelism(){return 1;}public void execute(Runnable r){if(r==null)throw new NullPointerException();if(shutdown)throw new RejectedExecutionException();new Thread(r).start();}public void shutdown(){if(this!=COMMON)shutdown=true;}public java.util.List<Runnable> shutdownNow(){shutdown();return new java.util.ArrayList<Runnable>();}public boolean isShutdown(){return shutdown;}public boolean isTerminated(){return shutdown;}public boolean awaitTermination(long n,TimeUnit u)throws InterruptedException{if(u==null)throw new NullPointerException();java.lang.VMThread.runPending();return shutdown;}}
